26: /// Owned tile grid + cached dimensions. `T` is the per-tile value —
27: /// usually an enum like `TileKind` — and needs to be `Copy + Default`
28: /// so out-of-bounds reads can synthesise a safe fill without touching
29: /// the backing store.
30: #[derive(Clone, Debug, Default)]
31: pub struct TileGrid<T: Copy + Default> {
32:     grid: Vec<T>,
33:     w: u32,
34:     h: u32,
35: }
36: 
37: impl<T: Copy + Default> TileGrid<T> {
38:     /// Empty grid — no storage, `dims() == (0, 0)`. Callers rebuild it
39:     /// from source data via [`TileGrid::rebuild_from_rows`] or by
40:     /// filling with [`TileGrid::new_filled`].
41:     pub fn empty() -> Self { Self { grid: Vec::new(), w: 0, h: 0 } }
42: 
43:     /// Allocate `w*h` tiles all initialised to `val`. `T: Default` is
44:     /// only required at the type level; `val` can be any value.
45:     pub fn new_filled(w: u32, h: u32, val: T) -> Self {
46:         Self { grid: vec![val; (w * h) as usize], w, h }
47:     }
48: 
49:     /// (Width, height) in tiles.
50:     #[inline]
51:     pub fn dims(&self) -> (u32, u32) { (self.w, self.h) }
52: 
53:     /// Width in tiles.
54:     #[inline]
55:     pub fn width(&self) -> u32 { self.w }
56: 
57:     /// Height in tiles.
58:     #[inline]
59:     pub fn height(&self) -> u32 { self.h }
60: 
61:     /// True when `dims()` is `(0, 0)`. Cheap sentinel used by fixture
62:     /// code paths that construct a value via `..Default::default()`
63:     /// and never call `rebuild_from_rows`.
64:     #[inline]
65:     pub fn is_empty(&self) -> bool { self.grid.is_empty() }
66: 
67:     /// Read at `(col, row)`. Out-of-bounds (including negative) reads
68:     /// return `T::default()` so callers can walk past the edge without
69:     /// a pre-check — collision, pathfinding, and neighbour scans rely
70:     /// on this.
71:     #[inline]
72:     pub fn tile_at(&self, col: i32, row: i32) -> T {
73:         if col < 0 || row < 0 || self.grid.is_empty() { return T::default(); }
74:         let (c, r) = (col as u32, row as u32);
75:         if c >= self.w || r >= self.h { return T::default(); }
76:         self.grid[(r * self.w + c) as usize]
77:     }
78: 
79:     /// True if `(col, row)` is inside the grid bounds.
80:     #[inline]
81:     pub fn in_bounds(&self, col: i32, row: i32) -> bool {
82:         col >= 0 && row >= 0 && (col as u32) < self.w && (row as u32) < self.h
83:     }
84: 
85:     /// Write at `(col, row)`. Silently no-ops when out of bounds; the
86:     /// editor's `set_tile` mutator relies on this to be safe against
87:     /// stray clicks past the grid edge.
88:     #[inline]
89:     pub fn set(&mut self, col: i32, row: i32, val: T) {
90:         if !self.in_bounds(col, row) || self.grid.is_empty() { return; }
91:         let idx = (row as u32 * self.w + col as u32) as usize;
92:         self.grid[idx] = val;
93:     }
94: 
95:     /// Fill every tile with `val`, keeping the current dimensions.
96:     pub fn fill(&mut self, val: T) {
97:         for c in self.grid.iter_mut() { *c = val; }
98:     }
99: 
100:     /// Borrow the flat backing buffer, row-major `r*w + c`.
101:     #[inline]
102:     pub fn as_slice(&self) -> &[T] { &self.grid }
103: 
104:     /// Iterate every cell as `(col, row, val)` in row-major scan order.
105:     pub fn iter_cells(&self) -> impl Iterator<Item = (u32, u32, T)> + '_ {
106:         let w = self.w;
107:         self.grid.iter().enumerate().map(move |(i, &v)| {
108:             let i = i as u32;
109:             (i % w, i / w, v)
110:         })
111:     }
112: 
113:     /// Rebuild storage from a row-major provider. `w` / `h` are set to
114:     /// the passed dims and every cell is filled by calling `read(c, r)`.
115:     /// The standard use is decoding a `Vec<String>` of glyphs into
116:     /// enum tiles — pass a closure that indexes into the strings, or
117:     /// prefer [`TileGrid::rebuild_from_glyphs`] which handles that
118:     /// pattern directly.
119:     pub fn rebuild_from_rows<F>(&mut self, w: u32, h: u32, mut read: F)
120:     where
121:         F: FnMut(u32, u32) -> T,
122:     {
123:         self.w = w;
124:         self.h = h;
125:         let mut buf = Vec::with_capacity((w * h) as usize);
126:         for r in 0..h {
127:             for c in 0..w {
128:                 buf.push(read(c, r));
129:             }
130:         }
131:         self.grid = buf;
132:     }
133: 
134:     /// Rebuild from a `&[String]` of glyph rows via a `char -> T`
135:     /// decoder. Dims are derived from the string vec (height = row
136:     /// count, width = first row's byte length). Bytes past a short
137:     /// row and unmapped chars fall through to `T::default()`. Every
138:     /// tile-file loader in the project (station floors, ship
139:     /// interiors, module tiles) shares this exact decode path.
140:     pub fn rebuild_from_glyphs<F>(&mut self, tiles: &[String], mut decode: F)
141:     where
142:         F: FnMut(char) -> T,
143:     {
144:         let h = tiles.len() as u32;
145:         let w = tiles.first().map(|r| r.len() as u32).unwrap_or(0);
146:         self.rebuild_from_rows(w, h, |c, r| {
147:             tiles.get(r as usize)
148:                 .and_then(|row| row.as_bytes().get(c as usize).copied())
149:                 .map(|b| decode(b as char))
150:                 .unwrap_or_default()
151:         });
152:     }
153: 
154:     /// Read a `(col, row)` from a `&[String]` of glyph rows without a
155:     /// prebuilt grid. Returns `T::default()` for out-of-range or short
156:     /// rows. Used by the `tile_at` fallback path on fresh-from-`serde`
157:     /// instances where `rebuild_from_glyphs` hasn't run yet.
158:     pub fn tile_at_glyphs<F>(tiles: &[String], col: i32, row: i32, mut decode: F) -> T
159:     where
160:         F: FnMut(char) -> T,
161:     {
162:         if col < 0 || row < 0 { return T::default(); }
163:         tiles.get(row as usize)
164:             .and_then(|s| s.as_bytes().get(col as usize).copied())
165:             .map(|b| decode(b as char))
166:             .unwrap_or_default()
167:     }
168: 
169:     /// World-space centre of tile `(col, row)`. Standard "grid centered
170:     /// on origin, row 0 at top" layout. Forwards to
171:     /// [`tile_center_default`] — kept as a method so callers reach it
172:     /// through the grid struct without a separate import.
173:     #[inline]
174:     pub fn tile_center(&self, col: u32, row: u32, tile_size_m: f32) -> DVec2 {
175:         tile_center_default(col as i32, row as i32, self.w, self.h, tile_size_m)
176:     }
177: 
178:     /// World-space position → `(col, row)`. Inverse of
179:     /// [`TileGrid::tile_center`]. Caller should range-check.
180:     #[inline]
181:     pub fn pos_to_tile(&self, pos: DVec2, tile_size_m: f32) -> (i32, i32) {
182:         pos_to_tile_default(pos, self.w, self.h, tile_size_m)
183:     }
184: }
185: 
186: /// Rotate a row-major `w * h` tile buffer by `rot` quarter-turns
187: /// clockwise (taken modulo 4), returning `(new_w, new_h, tiles)`.
188: ///
189: /// Odd quarter-turns transpose the dimensions. `rot == 0` is a straight
190: /// copy. Reads go through `src`, a `(col, row) -> T` closure, rather
191: /// than a slice, so callers whose canonical storage is glyph rows or a
192: /// lazily-populated cache can rotate without materialising a flat buffer
193: /// first.
194: ///
195: /// Extracted because `void_sim::module::Module::rotated_tiles` and the
196: /// tilemap editor's `Clipboard::rotated` carried byte-identical copies
197: /// of this kernel, and a divergence between them would silently desync
198: /// the editor preview from the runtime composite.
199: pub fn rotate_tiles<T, F>(w: u32, h: u32, rot: u8, mut src: F) -> (u32, u32, Vec<T>)
200: where
201:     T: Copy + Default,
202:     F: FnMut(u32, u32) -> T,
203: {
204:     let rot = rot % 4;
205:     let (sw, sh) = (w as usize, h as usize);
206:     let (nw, nh) = match rot {
207:         1 | 3 => (sh, sw),
208:         _     => (sw, sh),
209:     };
210:     let mut out = vec![T::default(); nw * nh];
211:     for r in 0..sh {
212:         for c in 0..sw {
213:             let val = src(c as u32, r as u32);
214:             let (nc, nr) = match rot {
215:                 0 => (c, r),
216:                 1 => (sh - 1 - r, c),          // 90° CW
217:                 2 => (sw - 1 - c, sh - 1 - r), // 180°
218:                 3 => (r, sw - 1 - c),          // 270° CW (= 90° CCW)
219:                 _ => unreachable!(),
220:             };
221:             out[nr * nw + nc] = val;
222:         }
223:     }
224:     (nw as u32, nh as u32, out)
225: }

