106:     pub fn alive(&self, id: EntityId) -> bool {
107:         self.alive
108:             .get(id.index as usize)
109:             .copied()
110:             .unwrap_or(false)
111:             && self.generations.get(id.index as usize).copied() == Some(id.generation)
112:     }
