8: /// Wrap the line containing `at` into chunks of at most `width` bytes.
9: ///
10: /// The line is taken by span, so this never allocates the whole file.
11: pub fn wrap_line(text: &str, at: usize, width: usize) -> Vec<String> {
12:     let s = line_span(text, at);
13:     let line = &text[s.start..s.end];
14:     let n = chunk_count(line.len(), width);
15:     let mut out = Vec::with_capacity(n);
16:     for k in 0..n {
17:         let i = (k * width).min(line.len());
18:         let j = (i + width).min(line.len());
19:         out.push(line[i..j].to_string());
20:     }
21:     out
22: }

