50:     fn name(&self) -> &'static str {
51:         "ring"
52:     }
53:     fn get(&self, key: &str) -> Option<String> {
54:         self.slots.iter().find(|(k, _)| k == key).map(|(_, v)| v.clone())
55:     }
56:     fn put(&mut self, key: &str, value: &str) {
57:         if let Some(slot) = self.slots.iter_mut().find(|(k, _)| k == key) {
58:             slot.1 = value.to_string();
59:             return;
60:         }
61:         if self.slots.len() < self.cap {
62:             self.slots.push((key.to_string(), value.to_string()));
63:         } else {
64:             self.slots[self.next] = (key.to_string(), value.to_string());
65:             self.next = (self.next + 1) % self.cap;
66:         }
67:     }
