1: //! Escaping for the log sink: a line-oriented format where a record is one line.
2: 
3: /// Escape `s` so it survives a round trip through the line-oriented log format.
4: ///
5: /// A record is one line, so a literal newline inside a field would split the
6: /// record in two. Newlines become `\n`, tabs become `\t`.
7: pub fn escape(s: &str) -> String {
8:     let mut out = String::with_capacity(s.len());
9:     for c in s.chars() {
10:         match c {
11:             '\n' => out.push_str("\\n"),
12:             '\t' => out.push_str("\\t"),
13:             _ => out.push(c),
14:         }
15:     }
16:     out
17: }
18: 
19: /// Undo [`escape`].
20: pub fn unescape(s: &str) -> String {
21:     let mut out = String::with_capacity(s.len());
22:     let mut it = s.chars();
23:     while let Some(c) = it.next() {
24:         if c != '\\' {
25:             out.push(c);
26:             continue;
27:         }
28:         match it.next() {
29:             Some('n') => out.push('\n'),
30:             Some('t') => out.push('\t'),
31:             Some('\\') => out.push('\\'),
32:             Some(other) => {
33:                 out.push('\\');
34:                 out.push(other);
35:             }
36:             None => out.push('\\'),
37:         }
38:     }
39:     out
40: }

